CREATE TABLE author (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name        text NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE book (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    author_id   bigint NOT NULL REFERENCES author(id) ON DELETE RESTRICT,
    title       text   NOT NULL,
    isbn        text   UNIQUE,
    published_at date  NOT NULL,
    CHECK (published_at <= current_date)        -- no future pub dates
);

-- Index the FK to avoid Seq Scans on DELETE from author:
CREATE INDEX book_author_id_idx ON book(author_id);

CREATE TABLE event (
    id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    payload    jsonb NOT NULL DEFAULT '{}'::jsonb
);

INSERT INTO event (payload) VALUES
    ('{"type":"click","page":"/home","user":{"id":42,"plan":"pro"},"tags":["a","b"]}');

SELECT
    payload -> 'type'         AS type_jsonb,    -- "click" (jsonb, with quotes)
    payload ->> 'type'        AS type_text,     -- click (text, no quotes)
    payload #>> '{user,plan}' AS user_plan,     -- pro
    payload -> 'tags' -> 0    AS first_tag      -- "a"
FROM event;

-- Containment (uses GIN if available):
SELECT * FROM event WHERE payload @> '{"type":"click"}';
-- Key existence:
SELECT * FROM event WHERE payload ? 'user';
-- Path existence (any of):
SELECT * FROM event WHERE payload ?| array['user','session'];

CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END $$;

CREATE TABLE post (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    title       text,
    body        text,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TRIGGER post_set_updated_at
    BEFORE UPDATE ON post
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

-- Parse a document and a query:
SELECT to_tsvector('english', 'The quick brown fox jumps over the lazy dog');
-- 'brown':3 'dog':9 'fox':4 'jumps':5 'lazy':8 'quick':2

SELECT websearch_to_tsquery('english', 'quick fox -dog');
-- 'quick' & 'fox' & !'dog'

-- Match (uses GIN if available):
SELECT to_tsvector('english', body) @@ websearch_to_tsquery('english', 'fox');

CREATE TABLE events (
    id          bigint GENERATED ALWAYS AS IDENTITY,
    tenant_id   bigint NOT NULL,
    occurred_at timestamptz NOT NULL,
    event_type  text NOT NULL,
    payload     jsonb NOT NULL DEFAULT '{}'::jsonb,
    PRIMARY KEY (id, occurred_at)            -- PK must include partition key
) PARTITION BY RANGE (occurred_at);

CREATE TABLE events_2024_01 PARTITION OF events
    FOR VALUES FROM ('2024-01-01') TO ('2024-02-01');
CREATE TABLE events_2024_02 PARTITION OF events
    FOR VALUES FROM ('2024-02-01') TO ('2024-03-01');
CREATE TABLE events_default PARTITION OF events DEFAULT;

-- The planner prunes to the relevant partition:
EXPLAIN SELECT count(*) FROM events
WHERE occurred_at >= '2024-01-15' AND occurred_at < '2024-01-20';
-- Shows: Seq Scan on events_2024_01 only (other partitions pruned)

-- Session A:
BEGIN ISOLATION LEVEL READ COMMITTED;
SELECT count(*) FROM events WHERE tenant_id = 1;   -- returns 100
-- Session B inserts 50 rows and commits
SELECT count(*) FROM events WHERE tenant_id = 1;   -- returns 150 (non-repeatable)
COMMIT;

-- Session A (REPEATABLE READ):
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT count(*) FROM events WHERE tenant_id = 1;   -- returns 100
-- Session B inserts 50 rows and commits
SELECT count(*) FROM events WHERE tenant_id = 1;   -- returns 100 (snapshot frozen)
COMMIT;

-- Application role: only DML on relevant tables, no SUPERUSER, no CREATE
CREATE ROLE app_user LOGIN PASSWORD 'use-env-secret'
    NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION
    CONNECTION LIMIT 50;

GRANT USAGE  ON SCHEMA public TO app_user;
GRANT SELECT, INSERT, UPDATE, DELETE
    ON ALL TABLES IN SCHEMA public TO app_user;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
    GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO app_user;

-- Analyst role: read-only, but with sensitive columns hidden
CREATE ROLE analyst LOGIN PASSWORD 'env-secret';
GRANT SELECT (id, name, department_id, hire_date) ON employee TO analyst;
-- analyst cannot SELECT salary or ssn

CREATE EXTENSION postgis;

CREATE TABLE store (
    id      bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name    text NOT NULL,
    geom    geometry(Point, 4326) NOT NULL           -- SRID 4326 = WGS84
);

CREATE INDEX store_geom_gist ON store USING gist (geom);

-- Find stores within 5 km of a point (geography for distance in meters):
SELECT id, name,
    ST_Distance(geom::geography, ST_MakePoint(-122.42, 37.78)::geography) AS dist_m
FROM store
WHERE ST_DWithin(geom::geography, ST_MakePoint(-122.42, 37.78)::geography, 5000)
ORDER BY dist_m
LIMIT 20;
